H.background();
const phi = P.phi;
const A = 0.6;
const k = 2 * Math.PI / 2;
const w = 2 * Math.PI * 0.5;
H.text("Superposition: y = y₁ + y₂", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Phase φ = 0 -> constructive (2A); φ = π -> destructive (≈0)", 24, 52, { color: H.colors.sub, size: 13 });
const view = H.plot2d({ xMin: 0, xMax: 4, yMin: -1.4, yMax: 1.4 });
view.axes();
const y1 = x => A * Math.sin(k * x - w * t);
const y2 = x => A * Math.sin(k * x - w * t + phi);
view.fn(y1, { color: H.colors.sub, width: 1 });
view.fn(y2, { color: H.colors.violet, width: 1 });
view.fn(x => y1(x) + y2(x), { color: H.colors.accent, width: 3 });
const Ares = 2 * A * Math.abs(Math.cos(phi / 2));
view.line(0, Ares, 4, Ares, { color: H.colors.warn, width: 1, dash: [4, 4] });
view.line(0, -Ares, 4, -Ares, { color: H.colors.warn, width: 1, dash: [4, 4] });
const xc = (w * t / k) % 4;
view.dot(xc, y1(xc) + y2(xc), { r: 6, fill: H.colors.warn });
H.legend([{ label: "y1", color: H.colors.sub }, { label: "y2 (shifted)", color: H.colors.violet }, { label: "y1+y2", color: H.colors.accent }], 24, 470);
H.text("φ = " + phi.toFixed(2) + " rad (" + (phi * 180 / Math.PI).toFixed(0) + "°)", 24, 76, { color: H.colors.sub, size: 13 });
H.text("Resultant amplitude = 2A|cos(φ/2)| = " + Ares.toFixed(2) + " m", 24, 96, { color: H.colors.accent2, size: 13 });
